def transform(grid):
    from collections import Counter

    color_counts = Counter(v for row in grid for v in row)
    uniform_rows = [
        (i, row[0]) for i, row in enumerate(grid)
        if all(v == row[0] for v in row)
    ]
    sep, _ = min(uniform_rows, key=lambda item: color_counts[item[1]])

    upper = grid[:sep]
    lower = grid[sep + 1:]
    background = Counter(v for row in lower for v in row).most_common(1)[0][0]

    return [
        [2 if upper[r][c] != 0 and lower[r][c] != background else 0
         for c in range(len(upper[r]))]
        for r in range(len(upper))
